"use client";

import { useId, useState } from "react";

import { Slider } from "@/components/motion/slider";

import { BlockFrame } from "../parts/block-frame";
import { BillingToggle } from "./shared/billing-toggle";
import { formatCount, plural } from "./shared/money";
import type { Billing } from "./shared/plans";
import { CostBreakdown } from "./usage-pricing/cost-breakdown";
import { BOOKING_STOPS, MAX_SEATS, recommend } from "./usage-pricing/data";
import { PlanPanel } from "./usage-pricing/plan-panel";
import { StopLabels } from "./shared/stop-labels";

/**
 * A pricing calculator that picks the plan for you. Move the practitioners
 * and bookings sliders, choose a billing period, and read each line of the
 * estimate beside the cheapest plan that fits and the rule that chose it.
 */
export function UsagePricing({ className }: { className?: string }) {
  const titleId = useId();
  const [seats, setSeats] = useState(6);
  const [bookingIndex, setBookingIndex] = useState(5);
  const [billing, setBilling] = useState<Billing>("monthly");

  const bookings = BOOKING_STOPS[bookingIndex] ?? 0;
  const { best, reason } = recommend(seats, bookings, billing);
  const lastBooking = BOOKING_STOPS.length - 1;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div className="grid gap-6 p-5 @2xl:p-8 @4xl:grid-cols-[1fr_22rem]">
        <div className="flex min-w-0 flex-col gap-6">
          <header className="flex flex-col gap-1">
            <h2 id={titleId} className="text-xl font-semibold tracking-tight">
              Find your Fernhill plan
            </h2>
            <p className="text-sm text-muted-foreground">
              Tell us how big your clinic is. We pick the cheapest plan and show
              how the price adds up.
            </p>
          </header>

          <div className="-mx-3 overflow-x-clip px-3">
            <Slider
              label="Practitioners"
              min={1}
              max={MAX_SEATS}
              value={seats}
              onValueChange={setSeats}
              formatValue={(value) => plural(value, "practitioner")}
            />
            <StopLabels
              stops={[
                { at: 0, label: "1" },
                { at: (25 - 1) / (MAX_SEATS - 1), label: "Practice up to 25" },
                { at: 1, label: String(MAX_SEATS) },
              ]}
            />
          </div>

          <div className="-mx-3 overflow-x-clip px-3">
            <Slider
              label="Bookings a month"
              min={0}
              max={lastBooking}
              value={bookingIndex}
              onValueChange={setBookingIndex}
              formatValue={(index) => formatCount(BOOKING_STOPS[index] ?? 0)}
            />
            <StopLabels
              stops={[
                { at: 0, label: formatCount(BOOKING_STOPS[0] ?? 0) },
                {
                  at: BOOKING_STOPS.indexOf(10_000) / lastBooking,
                  label: "10,000",
                },
                { at: 1, label: formatCount(BOOKING_STOPS[lastBooking] ?? 0) },
              ]}
            />
          </div>

          <BillingToggle
            value={billing}
            onValueChange={setBilling}
            className="self-start"
          />

          <CostBreakdown quote={best} seats={seats} billing={billing} />
        </div>

        <PlanPanel quote={best} reason={reason} billing={billing} />
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { SegmentedControl } from "@/components/motion/segmented-control";

import { type Billing, YEARLY_SAVING } from "./plans";

const OPTIONS = [
  { value: "monthly" as const, label: "Monthly" },
  {
    value: "yearly" as const,
    label: (
      <span className="inline-flex items-center gap-1.5">
        Yearly
        <span className="text-xs font-semibold text-marketing-green-ink">
          Save {Math.round(YEARLY_SAVING * 100)}%
        </span>
      </span>
    ),
  },
];

/**
 * Switches between monthly and yearly billing and shows the yearly saving.
 * It is a radio group, so arrow keys switch the period.
 */
export function BillingToggle({
  value,
  onValueChange,
  className,
}: {
  value: Billing;
  onValueChange: (value: Billing) => void;
  className?: string;
}) {
  return (
    <SegmentedControl
      aria-label="Billing period"
      options={OPTIONS}
      value={value}
      onValueChange={onValueChange}
      className={className}
    />
  );
}

/** How often a clinic pays. */
export type Billing = "monthly" | "yearly";

/** The three Fernhill plans, smallest first. */
export type PlanId = "solo" | "practice" | "group";

/** One Fernhill plan and what it includes. */
export interface Plan {
  id: PlanId;
  name: string;
  /** Who the plan is for, in a few words. */
  audience: string;
  /** The price of one practitioner seat for one month, billed monthly. */
  seatPrice: number;
  /** The most practitioners the plan holds, or null for no limit. */
  seatLimit: number | null;
  /** Bookings a month the plan includes before each extra booking costs more. */
  bookingsIncluded: number;
}

/** Yearly billing takes this share off every price. */
export const YEARLY_SAVING = 0.2;

/** The cost of each booking past a plan's included amount. */
export const EXTRA_BOOKING_PRICE = 0.03;

/** The plans in size order. */
export const PLANS: Plan[] = [
  {
    id: "solo",
    name: "Solo",
    audience: "One room, a few practitioners",
    seatPrice: 14,
    seatLimit: 3,
    bookingsIncluded: 1_000,
  },
  {
    id: "practice",
    name: "Practice",
    audience: "A busy clinic with a front desk",
    seatPrice: 24,
    seatLimit: 25,
    bookingsIncluded: 10_000,
  },
  {
    id: "group",
    name: "Group",
    audience: "Several clinics under one roof",
    seatPrice: 38,
    seatLimit: null,
    bookingsIncluded: 50_000,
  },
];

/** The price of one seat for one month under a billing period. */
export const seatPriceFor = (plan: Plan, billing: Billing) =>
  billing === "yearly" ? plan.seatPrice * (1 - YEARLY_SAVING) : plan.seatPrice;

/** True when the plan has room for this many practitioners. */
export const holdsSeats = (plan: Plan, seats: number) =>
  plan.seatLimit === null || seats <= plan.seatLimit;

/** The smallest plan that has room for this many practitioners. */
export const smallestPlanFor = (seats: number) =>
  PLANS.find((plan) => holdsSeats(plan, seats)) ?? PLANS[PLANS.length - 1]!;

const CENTS = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});
const DOLLARS = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});
const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });

/** Rounds an amount to whole cents, so every line of a sum adds up to the shown total. */
export const toCents = (value: number) => Math.round(value * 100) / 100;

/** A dollar amount with cents, such as $1,843.20. */
export const formatCents = (value: number) => CENTS.format(toCents(value));

/** A dollar amount with no cents, such as $240. */
export const formatDollars = (value: number) =>
  DOLLARS.format(Math.round(value));

/** A whole number with thousands separators, such as 12,000. */
export const formatCount = (value: number) => WHOLE.format(Math.round(value));

/** A price that may need cents: $24 stays whole, $19.20 keeps its cents. */
export const formatPrice = (value: number) =>
  Number.isInteger(toCents(value)) ? formatDollars(value) : formatCents(value);

/** Writes a count with its noun, such as "1 seat" or "12 seats". */
export const plural = (count: number, one: string, many = `${one}s`) =>
  `${formatCount(count)} ${count === 1 ? one : many}`;

"use client";

import { RollingText } from "@/components/blocks/parts/rolling-text";

import { formatCents, formatCount, plural } from "../shared/money";
import {
  type Billing,
  EXTRA_BOOKING_PRICE,
  YEARLY_SAVING,
} from "../shared/plans";
import { Reveal } from "../shared/reveal";
import type { Quote } from "./data";

/**
 * Lists each line of the monthly sum for the recommended plan, then the
 * estimated total. Lines that do not apply close their height.
 */
export function CostBreakdown({
  quote,
  seats,
  billing,
}: {
  quote: Quote;
  seats: number;
  billing: Billing;
}) {
  return (
    <section
      aria-label="How the estimate adds up"
      className="rounded-xl border border-border"
    >
      <dl className="flex flex-col px-4 py-2 text-sm">
        <div className="flex items-baseline justify-between gap-4 py-2">
          <dt className="min-w-0 text-muted-foreground">
            {quote.plan.name} seats, {plural(seats, "seat")} at{" "}
            {formatCents(quote.plan.seatPrice)}
          </dt>
          <dd>
            <RollingText text={formatCents(quote.seatsAtList)} />
          </dd>
        </div>
        <Reveal show={billing === "yearly"}>
          <div className="flex items-baseline justify-between gap-4 py-2">
            <dt className="text-muted-foreground">
              Yearly billing, {Math.round(YEARLY_SAVING * 100)}% off seats
            </dt>
            <dd className="text-marketing-green-ink">
              <RollingText text={`-${formatCents(quote.saving)}`} />
            </dd>
          </div>
        </Reveal>
        <Reveal show={quote.extraBookings > 0}>
          <div className="flex items-baseline justify-between gap-4 py-2">
            <dt className="min-w-0 text-muted-foreground">
              {formatCount(quote.extraBookings)} extra bookings at{" "}
              {formatCents(EXTRA_BOOKING_PRICE)}
            </dt>
            <dd>
              <RollingText text={formatCents(quote.extraCost)} />
            </dd>
          </div>
        </Reveal>
        <div className="mt-1 flex items-baseline justify-between gap-4 border-t border-border pt-3 pb-1">
          <dt className="font-medium">Estimated a month</dt>
          <dd className="text-lg font-semibold">
            <RollingText text={formatCents(quote.total)} />
          </dd>
        </div>
      </dl>
    </section>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";
import type { ReactNode } from "react";

// Critically damped, so a line opens and settles without a bounce.
const HEIGHT: Transition = {
  type: "spring",
  stiffness: 420,
  damping: 42,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/** Props for content that opens and closes its height. */
export interface RevealProps {
  show: boolean;
  children: ReactNode;
  className?: string;
}

/**
 * Opens its content from zero height with a fade and closes it the same way,
 * so the lines under it glide instead of jumping. Reduced motion shows and
 * hides it at once.
 */
export function Reveal({ show, children, className }: RevealProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : HEIGHT;
  return (
    <AnimatePresence initial={false}>
      {show ? (
        <motion.div
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          transition={transition}
          className="overflow-hidden"
        >
          <div className={className}>{children}</div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

import { formatCount } from "../shared/money";
import {
  type Billing,
  EXTRA_BOOKING_PRICE,
  holdsSeats,
  type Plan,
  type PlanId,
  PLANS,
  seatPriceFor,
} from "../shared/plans";

/** The bookings a month the second slider stops at. */
export const BOOKING_STOPS = [
  250, 500, 1_000, 2_000, 3_500, 5_000, 7_500, 10_000, 15_000, 20_000, 30_000,
  50_000, 75_000,
];

/** The most practitioners the first slider reaches. */
export const MAX_SEATS = 60;

/** One included limit of a plan, as a row. */
export interface IncludedRow {
  label: string;
  value: string;
}

/** What each plan includes. The lists differ in length, so the panel reflows as the plan changes. */
export const INCLUDED = {
  solo: [
    { label: "Practitioners", value: "Up to 3" },
    { label: "Bookings a month", value: "1,000" },
    { label: "Room calendars", value: "1" },
    { label: "Reminders", value: "Text and email" },
  ],
  practice: [
    { label: "Practitioners", value: "Up to 25" },
    { label: "Bookings a month", value: "10,000" },
    { label: "Room calendars", value: "8" },
    { label: "Reminders", value: "Text and email" },
    { label: "Front desk check-in", value: "Included" },
  ],
  group: [
    { label: "Practitioners", value: "No limit" },
    { label: "Bookings a month", value: "50,000" },
    { label: "Room calendars", value: "No limit" },
    { label: "Reminders", value: "Text, email and voice" },
    { label: "Front desk check-in", value: "Included" },
    { label: "Reports across clinics", value: "Included" },
  ],
} satisfies Record<PlanId, IncludedRow[]>;

/** The parts of one plan's monthly cost for a team and a booking volume. */
export interface Quote {
  plan: Plan;
  /** Seats at the monthly list price. */
  seatsAtList: number;
  /** What yearly billing takes off the seats. Zero when billed monthly. */
  saving: number;
  extraBookings: number;
  extraCost: number;
  total: number;
}

/** Prices one plan. Extra bookings are never discounted, so yearly billing saves on seats alone. */
export function quote(
  plan: Plan,
  seats: number,
  bookings: number,
  billing: Billing,
): Quote {
  const seatsAtList = plan.seatPrice * seats;
  const saving = seatsAtList - seatPriceFor(plan, billing) * seats;
  const extraBookings = Math.max(0, bookings - plan.bookingsIncluded);
  const extraCost = extraBookings * EXTRA_BOOKING_PRICE;
  return {
    plan,
    seatsAtList,
    saving,
    extraBookings,
    extraCost,
    total: seatsAtList - saving + extraCost,
  };
}

/** The cheapest plan that holds the team, and a sentence that says why it won. */
export function recommend(seats: number, bookings: number, billing: Billing) {
  const quotes = PLANS.map((plan) => quote(plan, seats, bookings, billing));
  const eligible = quotes.filter((item) => holdsSeats(item.plan, seats));
  const best = eligible.reduce((low, item) =>
    item.total < low.total ? item : low,
  );
  const at = PLANS.indexOf(best.plan);
  const before = at > 0 ? quotes[at - 1] : undefined;

  let reason: string;
  if (before && !holdsSeats(before.plan, seats)) {
    reason = `${before.plan.name} holds up to ${formatCount(before.plan.seatLimit ?? 0)} practitioners, so ${best.plan.name} is the smallest plan that fits.`;
  } else if (before) {
    reason = `${before.plan.name} would need ${formatCount(before.extraBookings)} extra bookings a month, so ${best.plan.name} costs less.`;
  } else if (best.extraBookings > 0) {
    reason = `${best.plan.name} is still the cheapest, even with ${formatCount(best.extraBookings)} extra bookings.`;
  } else {
    reason = `${best.plan.name} covers your team and every booking.`;
  }
  return { best, reason };
}

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";

import { ChevronRightIcon } from "@/components/blocks/parts/icons";
import { RollingText } from "@/components/blocks/parts/rolling-text";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatCents } from "../shared/money";
import { type Billing, PLANS } from "../shared/plans";
import { INCLUDED, type Quote } from "./data";

const SPRING: Transition = {
  type: "spring",
  stiffness: 420,
  damping: 38,
  mass: 1,
};
const MORPH: Transition = { duration: 0.24, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

const SEGMENT = ["bg-chart-2", "bg-chart-1", "bg-chart-4"];

/** Props for the recommended plan panel. */
export interface PlanPanelProps {
  quote: Quote;
  reason: string;
  billing: Billing;
}

/**
 * Shows the plan the sliders point to: a three-step size meter, the plan
 * name, the rule that picked it, its monthly price, what it includes and a
 * start button. The name morphs into the next plan's name when it changes.
 */
export function PlanPanel({ quote, reason, billing }: PlanPanelProps) {
  const reduceMotion = useReducedMotion();
  const plan = quote.plan;
  const step = PLANS.indexOf(plan);
  const rows = INCLUDED[plan.id];

  return (
    <section
      aria-label="Recommended plan"
      className="flex flex-col gap-5 rounded-xl border border-border bg-background p-5"
    >
      <div className="flex flex-col gap-2">
        <div aria-hidden="true" className="grid grid-cols-3 gap-1.5">
          {PLANS.map((item, index) => (
            <span
              key={item.id}
              className="h-1.5 overflow-hidden rounded-full bg-muted"
            >
              <motion.span
                initial={false}
                animate={{ scaleX: index <= step ? 1 : 0 }}
                transition={reduceMotion ? INSTANT : SPRING}
                className={cn(
                  "block h-full origin-left rounded-full",
                  SEGMENT[index],
                )}
              />
            </span>
          ))}
        </div>
        <div
          aria-hidden="true"
          className="grid grid-cols-3 gap-1.5 text-xs text-muted-foreground"
        >
          {PLANS.map((item, index) => (
            <span
              key={item.id}
              className={cn(index === step && "font-medium text-foreground")}
            >
              {item.name}
            </span>
          ))}
        </div>
      </div>

      <div aria-live="polite" className="flex flex-col gap-1">
        <h3 className="relative flex h-9 items-center overflow-hidden text-2xl font-semibold tracking-tight">
          <span className="sr-only">Recommended: </span>
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.span
              key={plan.id}
              initial={{ opacity: 0, y: "60%", filter: "blur(0.25rem)" }}
              animate={{ opacity: 1, y: 0, filter: "blur(0rem)" }}
              exit={{ opacity: 0, y: "-60%", filter: "blur(0.25rem)" }}
              transition={reduceMotion ? INSTANT : MORPH}
              className="inline-block"
            >
              {plan.name}
            </motion.span>
          </AnimatePresence>
        </h3>
        <p className="text-sm text-muted-foreground">{reason}</p>
      </div>

      <p className="flex flex-wrap items-baseline gap-x-1.5">
        <RollingText
          text={formatCents(quote.total)}
          className="text-3xl font-semibold tracking-tight"
        />
        <span className="text-sm text-muted-foreground">
          a month{billing === "yearly" ? ", billed yearly" : ""}
        </span>
      </p>

      <ul
        className="flex flex-col text-sm"
        aria-label={`${plan.name} includes`}
      >
        <AnimatePresence initial={false} mode="popLayout">
          {rows.map((row) => (
            <motion.li
              key={row.label}
              layout={!reduceMotion}
              initial={reduceMotion ? false : { opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={reduceMotion ? INSTANT : SPRING}
              className="flex items-baseline justify-between gap-4 py-1.5"
            >
              <span className="text-muted-foreground">{row.label}</span>
              <span className="text-right font-medium">{row.value}</span>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>

      <motion.div
        layout={!reduceMotion}
        transition={SPRING}
        className="flex flex-col gap-2"
      >
        <Button type="button" size="lg">
          Start a free trial of {plan.name}
          <ChevronRightIcon aria-hidden="true" />
        </Button>
        <p className="text-center text-xs text-muted-foreground">
          14 days free. Fernhill asks for no card until the trial ends.
        </p>
      </motion.div>
    </section>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
