import type { CSSProperties } from "react";
import { cn } from "@/lib/utils";

/** One labelled point under a slider, at a fraction of its track from 0 to 1. */
export interface StopLabel {
  at: number;
  label: string;
}

/**
 * Labels a few points under a slider track, such as where a plan's limit
 * sits. The labels at either end align to the edge so they never overflow.
 * They repeat what the slider already says, so screen readers skip them.
 */
export function StopLabels({ stops }: { stops: StopLabel[] }) {
  return (
    <div
      aria-hidden="true"
      className="relative mt-1 h-4 text-xs whitespace-nowrap text-muted-foreground tabular-nums"
    >
      {stops.map((stop) => (
        <span
          key={stop.label}
          className={cn(
            "absolute top-0 left-(--at)",
            stop.at <= 0
              ? "translate-x-0"
              : stop.at >= 1
                ? "-translate-x-full"
                : "-translate-x-1/2",
          )}
          style={
            // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
            { "--at": `${stop.at * 100}%` } as CSSProperties
          }
        >
          {stop.label}
        </span>
      ))}
    </div>
  );
}
